/**
 * The header's drop-down menus (20 November 2026).
 *
 * Chosen by the user from twelve variations built into copies of this page in
 * the design archive (submenu-lab, variation 8). The engine there served all
 * twelve; this is it cut to what the chosen one uses. The markup is dropMenus
 * in src/markup/page.js; the look is src/styles/submenu.css.
 */
/* ---------------------------------------------------------------------
   WHEN A MENU SHOWS. Wide screens only: below 1040px the header has no tabs.

   A mouse resting on a tab opens it after 110ms, so merely passing over does
   not; moving to another tab switches at once; leaving closes after 260ms,
   enough to cross from the tab to its panel. A click or tap on a closed tab
   opens it instead of travelling, which is what a touch screen needs; on an
   open tab it travels to the part, as the tab always did. So a mouse reader,
   whose pointer has already opened the menu, still reaches the part in one
   click. Keyboard: Enter or Space or ArrowDown opens and moves into the
   menu; arrows move within it; Escape closes and returns to the tab; leaving
   the menu by Tab closes it. So does a click elsewhere, and scrolling more
   than a little while a menu opened by a click or a key is up.

   CHOOSING A PLACE closes the menu, and the page's own travel (anchors.js)
   takes the reader to the link's address. A portfolio's overview is opened
   first, and a way of working filters the Impact wall first, so the reader
   arrives at what they chose, not at the page that lists it. */
(function () {
  var root = document.querySelector('.nav-links.sm');
  if (!root) return;
  var bar = document.querySelector('.nav-in');
  var wide = matchMedia('(min-width: 1040px)');
  var items = [].slice.call(root.querySelectorAll('.sm-item')).filter(function (item) {
    return item.querySelector('.sm-panel');
  });
  var cur = null, how = null, tOpen = 0, tShut = 0, openedAt = 0;

  function tabOf(item) { return item.querySelector('.sm-tab'); }
  function panelOf(item) { return item.querySelector('.sm-panel'); }
  function linksIn(item) { return [].slice.call(panelOf(item).querySelectorAll('.sm-link')); }

  /* A panel hangs under its own tab and moves left only as far as it must to
     keep its right edge inside the bar's. Measured from layout (offsetLeft,
     offsetWidth), never from the panel's rectangle, which is mid-transition
     at the moment a panel opens; and every panel is placed before it is
     first seen, so opening one never slides it sideways. */
  function fit(item) {
    if (!bar || !wide.matches) return;
    var panel = panelOf(item);
    var edge = bar.getBoundingClientRect().right - parseFloat(getComputedStyle(bar).paddingRight);
    var right = item.getBoundingClientRect().left + panel.offsetLeft + panel.offsetWidth;
    panel.style.setProperty('--fit', Math.min(0, Math.floor(edge - right)) + 'px');
  }
  function fitAll() { items.forEach(fit); }

  function open(item, why) {
    clearTimeout(tOpen);
    clearTimeout(tShut);
    if (cur === item) { if (why !== 'hover') how = why; return; }
    var from = cur;
    if (cur) {
      tabOf(cur).setAttribute('aria-expanded', 'false');
      cur.classList.remove('is-open');
    }
    cur = item;
    how = why;
    openedAt = scrollY;
    fit(item);
    tabOf(item).setAttribute('aria-expanded', 'true');
    item.classList.add('is-open');
    root.classList.toggle('is-switch', !!from);
  }
  function shut() {
    clearTimeout(tOpen);
    clearTimeout(tShut);
    if (!cur) return;
    tabOf(cur).setAttribute('aria-expanded', 'false');
    cur.classList.remove('is-open');
    root.classList.remove('is-switch');
    cur = null;
    how = null;
  }

  /* The mouse. */
  items.forEach(function (item) {
    item.addEventListener('pointerenter', function (e) {
      if (!wide.matches || e.pointerType !== 'mouse') return;
      clearTimeout(tShut);
      clearTimeout(tOpen);
      tOpen = setTimeout(function () { open(item, 'hover'); }, cur ? 0 : 110);
    });
  });
  root.addEventListener('pointerenter', function () { clearTimeout(tShut); });
  root.addEventListener('pointerleave', function (e) {
    if (e.pointerType !== 'mouse') return;
    clearTimeout(tOpen);
    if (cur && how === 'hover') tShut = setTimeout(shut, 260);
  });

  /* The tabs: click, tap and keys. */
  items.forEach(function (item) {
    var t = tabOf(item);
    t.addEventListener('click', function (e) {
      if (!wide.matches) return;
      if (cur !== item) {
        e.preventDefault();
        open(item, 'click');
        return;
      }
      shut();
    });
    t.addEventListener('keydown', function (e) {
      if (!wide.matches) return;
      if (e.key === 'ArrowDown' || e.key === ' ') {
        e.preventDefault();
        open(item, 'key');
        var first = linksIn(item)[0];
        if (first) first.focus();
      }
    });
  });
  root.addEventListener('keydown', function (e) {
    if (!cur) return;
    if (e.key === 'Escape') {
      var t = tabOf(cur);
      shut();
      t.focus();
      return;
    }
    var a = e.target.closest && e.target.closest('.sm-link');
    if (a && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
      e.preventDefault();
      var list = linksIn(cur);
      var i = list.indexOf(a) + (e.key === 'ArrowDown' ? 1 : -1);
      if (i < 0) { tabOf(cur).focus(); return; }
      if (list[i]) list[i].focus();
    }
  });
  root.addEventListener('focusout', function (e) {
    if (cur && (!e.relatedTarget || !root.contains(e.relatedTarget))) shut();
  });
  document.addEventListener('pointerdown', function (e) {
    if (cur && !root.contains(e.target)) shut();
  });
  addEventListener('scroll', function () {
    if (cur && how !== 'hover' && Math.abs(scrollY - openedAt) > 160) shut();
  }, { passive: true });
  wide.addEventListener('change', shut);

  /* Choosing a place. Nothing is prevented: anchors.js, listening further
     up, carries the reader to the link's own address once the overview is
     open or the wall filtered. */
  root.addEventListener('click', function (e) {
    var a = e.target.closest('.sm-link');
    if (!a) return;
    shut();
    var d = (a.getAttribute('data-deep') || '').split(':');
    if (d[0] === 'ov') {
      var btn = document.getElementById('ovb-' + d[1]);
      if (btn && !btn.hidden && btn.getAttribute('aria-expanded') !== 'true') btn.click();
    }
    if (d[0] === 'way') {
      var w = document.querySelector('.sw-btn[data-way="' + d[1] + '"]');
      if (w && !w.hidden && w.getAttribute('aria-pressed') !== 'true') w.click();
    }
  });

  /* Where the reader is: the chapter under a line a third of the way down,
     said in words beside it in the menu. */
  var secs = [].slice.call(document.querySelectorAll('.band[data-chapter]'));
  var rows = [].slice.call(root.querySelectorAll('.sm-row[data-target]'));
  var here = null, queued = false;
  function spy() {
    queued = false;
    var line = innerHeight * 0.35, id = null;
    for (var i = 0; i < secs.length; i++) {
      var r = secs[i].getBoundingClientRect();
      if (r.top <= line && r.bottom > line) { id = secs[i].id; break; }
    }
    if (id === here) return;
    here = id;
    rows.forEach(function (a) {
      var on = a.getAttribute('data-target') === id;
      a.classList.toggle('is-here', on);
      if (on) a.setAttribute('aria-current', 'location');
      else a.removeAttribute('aria-current');
    });
  }
  addEventListener('scroll', function () {
    if (!queued) { queued = true; requestAnimationFrame(spy); }
  }, { passive: true });
  spy();

  fitAll();
  addEventListener('load', fitAll);
  if (document.fonts) document.fonts.ready.then(fitAll);
  addEventListener('resize', fitAll, { passive: true });
})();
