/**
 * The scroll is eased, not hijacked. The window genuinely scrolls; only the
 * rate is smoothed.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
import { REDUCED } from './motion-base.js';
/* ── THE SCROLL IS EASED, NOT HIJACKED ────────────────────────────────────
   The window genuinely scrolls here; only the rate is smoothed. That
   distinction is the whole of it. The usual way to get this feel is to pin
   the document and translate a wrapper, which moves the content under a
   window whose scrollY never changes -- and this page is built on scrollY
   changing. The band arrivals, the marker in the margin and the navigation's
   own reading line are all driven by what the window reports, and every one
   of them would go quiet at once, and quietly, because none of them would
   error.

   Easing scrollY leaves every one of them working.

   Wheel only. Touch keeps the platform's own momentum, which is better than
   anything written here and is what a thumb expects. */
(function () {
  if (REDUCED.matches || matchMedia('(pointer: coarse)').matches) return;

  var target = scrollY, cur = scrollY, raf = 0, driving = false;
  var EASE = 0.12;

  function limit() { return Math.max(0, document.documentElement.scrollHeight - innerHeight); }

  function tick() {
    var d = target - cur;
    if (Math.abs(d) < 0.4) { cur = target; driving = false; raf = 0; scrollTo(0, cur); return; }
    cur += d * EASE;
    driving = true;
    scrollTo(0, cur);
    raf = requestAnimationFrame(tick);
  }

  addEventListener('wheel', function (e) {
    if (e.ctrlKey) return;                      /* a pinch zoom is not a scroll */

    /* Anything with a scrollbar of its own keeps its wheel. Without this the
       page eats the gesture and whatever the pointer is actually over -- an
       open overlay, a long list -- cannot be scrolled at all. */
    var n = e.target, depth = 0;
    while (n && n.nodeType === 1 && n !== document.body && depth++ < 8) {
      if (n.scrollHeight > n.clientHeight + 1) {
        var oy = getComputedStyle(n).overflowY;
        if (oy === 'auto' || oy === 'scroll') return;
      }
      n = n.parentNode;
    }

    /* deltaMode is not always pixels. Firefox reports lines, where deltaY is
       about 3 a notch rather than about 100, and a page that read it as
       pixels would barely move. */
    var dy = e.deltaY;
    if (e.deltaMode === 1) dy *= 16;
    else if (e.deltaMode === 2) dy *= innerHeight;

    e.preventDefault();
    target = Math.max(0, Math.min(limit(), target + dy));
    if (!raf) raf = requestAnimationFrame(tick);
  }, { passive: false });

  /* Anything that scrolls the page by another route -- a keyboard, the
     scrollbar, the eased jump an anchor click runs -- has to reset the
     target, or the next wheel yanks the page back to where this thought it
     was. */
  addEventListener('scroll', function () { if (!driving) { target = cur = scrollY; } }, { passive: true });
  addEventListener('resize', function () { target = cur = scrollY; }, { passive: true });
})();

