/**
 * What every other behaviour asks before it moves anything: whether the
 * reader asked for less motion, and how an element announces it has been
 * reached.
 *
 * Lifted verbatim from the approved page's one script. The only line that is
 * new is the export: `REDUCED` and `onReveal` were declared at the top of a
 * single long file and closed over by everything below them. They are
 * imported now, which is the same relationship written down.
 */

document.documentElement.classList.add('js');

const REDUCED = window.matchMedia('(prefers-reduced-motion: reduce)');
/* Reveals are opt-in enhancements over an already-visible default: if this
   script never runs, or the user asked for less motion, the page is complete. */
function onReveal(selector, fn, opts) {
  if (REDUCED.matches) return;
  const els = [].slice.call(document.querySelectorAll(selector));
  if (!els.length) return;

  const left = new Set(els);
  let io = null;
  function done(el) {
    if (!left.has(el)) return;
    left.delete(el);
    if (io) io.unobserve(el);
    fn(el);
  }

  if (!('IntersectionObserver' in window)) {
    els.forEach(done);
    return;
  }
  io = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) { if (e.isIntersecting) done(e.target); });
  }, Object.assign({ rootMargin: '0px 0px -20% 0px', threshold: 0 }, opts || {}));
  els.forEach(function (el) { io.observe(el); });

  /* The observer only reports what intersects at the moment it runs, so a fast
     scroll, an anchor jump, or End followed by Home can carry the viewport past
     an element and back without it ever being seen — which used to leave a
     whole page of copy at opacity 0 with no scroll left to recover it. So the
     depth the reader has actually reached is tracked, and anything that has
     been passed is revealed outright whether the observer noticed or not. The
     observer is the nicety; this is the guarantee.

     An entrance is for content you are arriving at. Content you have already
     flown past should simply be there. */
  let deepest = scrollY;
  let queued = false;
  function sweep() {
    queued = false;
    deepest = Math.max(deepest, scrollY);
    const reached = deepest + innerHeight;
    /* Array.from, not [].slice.call: slice on a Set yields an empty array and
       the sweep would silently do nothing. */
    Array.from(left).forEach(function (el) {
      if (el.getBoundingClientRect().top + scrollY < reached) done(el);
    });
    if (!left.size) removeEventListener('scroll', onScroll);
  }
  function onScroll() {
    if (queued) return;
    queued = true;
    requestAnimationFrame(sweep);
  }
  addEventListener('scroll', onScroll, { passive: true });
  sweep();

  /* And a hard backstop, because no page should be able to hold text hidden:
     whatever is still waiting after four seconds is shown. */
  setTimeout(function () { Array.from(left).forEach(done); }, 4000);
}


export { REDUCED, onReveal };
