/**
 * The menu below the collapse: the ink floods from the control, and the page
 * is held where it was.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
import { REDUCED } from './motion-base.js';
/* ── THE MENU BELOW THE COLLAPSE ─────────────────────────────────────────
   One attribute on <html> drives every transition in the stylesheet, so this
   only decides when it changes and looks after the keyboard.

   WHAT THE OVERLAY THIS REPLACES DID NOT DO, and a full-screen menu must:
   trap focus inside itself, give focus back to the control on close, take
   the page behind out of the tab order, and lock that page with
   position:fixed rather than overflow:hidden -- overflow is the lock iOS
   ignores, and the reader finds the page behind the menu scrolling under
   their finger. */
(function () {
  var btn = document.getElementById('fldBtn');
  var menu = document.getElementById('fldMenu');
  if (!btn || !menu) return;
  var ink = menu.querySelector('.fl-ink');
  var nav = document.getElementById('nav');
  var mark = document.querySelector('.nav .brand-mark');
  var flood = mark && mark.querySelector('.on-flood');
  var navInk = nav && nav.querySelector('.nav-ink');
  var root = document.documentElement;
  var main = document.getElementById('main');
  var foot = document.querySelector('.ft');
  var open = false, shutTimer = null, lockedScroll = 0;
  /* Both waits below exist to let a transition finish. Under reduced motion
     there is no transition to wait for, and making a reader who asked for
     less movement sit through its duration anyway is the bug that hides
     inside every hard-coded timeout. */
  var settle = function () { return REDUCED.matches ? 0 : 560; };
  var reach = function () { return REDUCED.matches ? 0 : 420; };

  /* Point one clipped layer at the same circle as the ink.
     THE CENTRE IS COMMITTED, NOT CHANGED. clip-path animates as a single
     property, centre and radius together, so writing these while the
     transition is live sends the circle flying in from the -9999px it parks
     at when shut -- which delivered the mark 150ms after the ink had already
     covered it. Switching the transition off, writing the values, forcing
     the browser to adopt them and handing it back makes them the starting
     state, leaving the radius as the only thing with anywhere to go. */
  function aim(host, layer, p, x, y, r) {
    if (!host || !layer) return;
    var q = host.getBoundingClientRect();
    layer.style.transition = 'none';
    host.style.setProperty('--' + p + 'x', (x - q.left) + 'px');
    host.style.setProperty('--' + p + 'y', (y - q.top) + 'px');
    host.style.setProperty('--' + p + 'r', Math.ceil(r) + 'px');
    void layer.offsetWidth;   /* reads layout, which is the whole point: it
                                 forces the centre to be adopted now.
                                 Deleting this line restores the bug. */
    layer.style.transition = '';
  }

  /* WHAT IS ACTUALLY ON SCREEN. visualViewport reports the rectangle the
     reader can see, which on a phone drifts away from the layout viewport
     every time the chrome retracts or a pinch-zoom moves. Everything else
     here is pinned to the sheet's own box, so getting this right is the only
     place the difference has to be handled. */
  var vv = window.visualViewport;
  function fitMenu() {
    var w = vv ? vv.width : innerWidth;
    var h = vv ? vv.height : innerHeight;
    menu.style.right = 'auto';
    menu.style.bottom = 'auto';
    menu.style.left = (vv ? vv.offsetLeft : 0) + 'px';
    menu.style.top = (vv ? vv.offsetTop : 0) + 'px';
    menu.style.width = w + 'px';
    menu.style.height = h + 'px';
  }
  function freeMenu() {
    menu.style.right = menu.style.bottom = menu.style.left =
      menu.style.top = menu.style.width = menu.style.height = '';
  }
  /* While it is open only. Listening always would run this on every scroll
     of every page view for a sheet that is not displayed. */
  function watchViewport(on) {
    if (!vv) return;
    var fn = on ? 'addEventListener' : 'removeEventListener';
    vv[fn]('resize', fitMenu);
    vv[fn]('scroll', fitMenu);
  }

  function focusables() {
    return [].slice.call(menu.querySelectorAll('a[href], button:not([disabled])'))
      .filter(function (el) { return el.offsetParent !== null; });
  }

  function setOpen(next) {
    if (next === open) return;
    open = next;
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');

    if (open) {
      clearTimeout(shutTimer);
      menu.setAttribute('data-live', '');
      /* The circle has to reach the furthest corner from wherever the control
         is, so the radius is the longest of the four diagonals, read on every
         open because the control moves with the viewport. */
      /* Sized before it is measured: the reach below is to the corners of
         the SHEET, not of the window, and on a phone those are two different
         rectangles. */
      fitMenu();
      watchViewport(true);
      var b = btn.getBoundingClientRect();
      var x = b.left + b.width / 2, y = b.top + b.height / 2;
      var m = menu.getBoundingClientRect();
      var far = Math.max(
        Math.hypot(x - m.left, y - m.top),
        Math.hypot(x - m.right, y - m.top),
        Math.hypot(x - m.left, y - m.bottom),
        Math.hypot(x - m.right, y - m.bottom)
      );
      /* THE INK GOES THROUGH THE SAME DOOR AS THE OTHER TWO. It used to have
         its properties written straight on, which looked harmless because
         its parked centre -- the top-right corner -- is within fifty pixels
         of where the control actually is. But writing them starts a
         transition on its centre there and then, a frame before the other
         two are released, and a frame of head start showed up as the ink
         running up to 42px ahead of the bar and the mark through the middle
         of the sweep. Three circles, one door, one starting line. */
      aim(ink, ink, '', x, y, far);
      /* THE SAME CIRCLE, IN THE MARK'S OWN COORDINATES. clip-path measures
         from the box it is applied to, and the lockup is a few dozen pixels
         in the corner while the ink is the whole screen, so the centre has
         to be restated relative to it. The radius does not: a distance is a
         distance wherever it is measured from.

         AND THE CENTRE IS COMMITTED, NOT CHANGED. clip-path animates as one
         property, centre and radius together, so writing these while the
         transition is live sends the circle flying in from the -9999px it
         parks at when shut -- it arrived at the letters 150ms after the ink
         had already covered them. Switching the transition off, writing the
         values, forcing the browser to adopt them and handing it back makes
         them the starting state, leaving the radius as the only thing with
         anywhere to go. */
      /* Both of them, the same way. Each clipped layer needs the centre in
         the coordinates of the box it is clipped against -- the lockup in
         the corner, the bar across the top -- and the radius unchanged,
         because a distance is a distance wherever it is measured from. */
      aim(mark, flood, 'm', x, y, far);
      aim(nav, navInk, 'n', x, y, far);
      /* Two frames, not one: the element has to be displayed and laid out
         before the attribute that starts the transition is set, or there is
         nothing to travel FROM and the ink simply appears. */
      requestAnimationFrame(function () {
        requestAnimationFrame(function () { root.setAttribute('data-menu', 'open'); });
      });
      /* THE PAGE MUST NOT JUMP AS IT LOCKS. Taking the page out of flow
         takes its scrollbar with it, the layout gets those pixels back, and
         the header and its mark slide sideways on the very frame the menu
         opens on. Giving the width back as padding holds everything still.
         Zero on a phone, which has no classic scrollbar, so this costs
         nothing where it is not needed. */
      var bar = innerWidth - document.documentElement.clientWidth;
      lockedScroll = scrollY;
      document.body.style.position = 'fixed';
      document.body.style.top = (-lockedScroll) + 'px';
      document.body.style.width = '100%';
      if (bar > 0) document.body.style.paddingRight = bar + 'px';
      [main, foot].forEach(function (el) { if (el) el.setAttribute('aria-hidden', 'true'); });
      /* The safety net. If the five do not fit the window after all, the
         header takes a ground so the list passes behind the mark rather than
         through it. Measured on the open menu rather than assumed from a
         breakpoint, because what overflows is type, and type does not know
         about breakpoints. */
      var inn = menu.querySelector('.fl-in');
      var tight = inn.scrollHeight > inn.clientHeight + 1;
      if (tight) menu.setAttribute('data-tight', '');
      else menu.removeAttribute('data-tight');
      var first = focusables()[0];
      if (first) setTimeout(function () { first.focus(); }, reach());
    } else {
      /* The drain is started LAST, below, so the sheet is still at full
         cover while the page is put where it is going. */
      document.body.style.position = '';
      document.body.style.top = '';
      document.body.style.width = '';
      document.body.style.paddingRight = '';
      var going = menu.querySelector('[data-going]');
      if (going) going.removeAttribute('data-going');
      /* BACK WHERE IT WAS, AND ONLY THEN ANNOUNCED. This restore used to run
         AFTER the announcement, and it went unnoticed for as long as the
         listener only started an animation -- that animation's first frame
         came later, so it read the restored position and all was well. The
         moment the listener did something immediate instead, this line
         overwrote it and the page sat where it started. The comment already
         claimed the page was back where it was before anyone was told; now
         the code agrees with it. */
      scrollTo(0, lockedScroll);
      /* THE PAGE IS SCROLLABLE AGAIN, AND BACK WHERE IT WAS. Anything that
         wanted to move it had to wait for this: a click on a destination
         fires the page's own jump on the same tick, and a jump that runs
         while the page is locked moves nothing at all. Announced rather than
         called, because the menu and the jump are separate pieces of this
         script and neither should hold a reference to the other. */
      menu.dispatchEvent(new CustomEvent('menushut', { bubbles: true }));
      /* AND NOW THE INK PULLS BACK, onto whatever the announcement just did.
         Setting this first -- which is where it used to be -- started the
         drain before the page had moved, so the last stretch of the journey
         happened in a corner the ink had already left. This way the sheet is
         at full cover for the move and the reveal lands on the destination,
         which is the whole idea the menu is built on. */
      root.setAttribute('data-menu', 'shut');
      [main, foot].forEach(function (el) { if (el) el.removeAttribute('aria-hidden'); });
      btn.focus();
      /* Held open until the ink has drained, or display:none cuts the exit
         off at its first frame. */
      watchViewport(false);
      shutTimer = setTimeout(function () {
        menu.removeAttribute('data-live');
        /* Only once it is out of the way: clearing the size while it is
           still draining would snap it back to the layout viewport in full
           view. */
        freeMenu();
      }, settle());
    }
  }

  btn.addEventListener('click', function () { setOpen(!open); });
  /* A destination takes gold, holds it for long enough to be seen, and the
     ink drains behind it. Closing instantly on the tap means the only
     feedback a phone can give is gone before the finger lifts. */
  menu.addEventListener('click', function (e) {
    var a = e.target.closest('a[href]');
    if (!a) return;
    a.setAttribute('data-going', '');
    setTimeout(function () { setOpen(false); }, REDUCED.matches ? 0 : 180);
  });

  addEventListener('keydown', function (e) {
    if (!open) return;
    if (e.key === 'Escape') { setOpen(false); return; }
    if (e.key !== 'Tab') return;
    var f = focusables();
    if (!f.length) return;
    var first = f[0], last = f[f.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  });

  /* Crossing the collapse with it open would leave the page locked against a
     menu that is no longer displayed. */
  addEventListener('resize', function () { if (innerWidth >= 1040 && open) setOpen(false); }, { passive: true });
})();


