/**
 * Impact: the story wall. Filter it by a way of working, and read a story in
 * a reader that opens beneath its row.
 *
 * Added on 17 November 2026, after the port; it is not lifted from the
 * approved page. It is written the way the lifted modules are, a body that
 * closes over REDUCED, so that the frozen reference can carry the same body
 * in its one inline script and tests/parity/assembly.mjs can hold the two to
 * the same hash. Its departure is recorded in tests/parity/extracted.sha256.json.
 */
import { REDUCED } from './motion-base.js';
/* ---------------------------------------------------------------------
   Impact: the story wall.

   THE WALL NEVER RESHUFFLES TO OPEN A STORY. The clicked tile stays where it
   is and a reader opens as a new row directly under it, its notch pointing up
   at the tile. The rows below slide down by the reader's height while the
   reader unrolls, both transforms and a clip, so nothing is laid out per
   frame, and the page glides on the same curve, only as far as it must.

   Every word it prints is the page's own: the account is copied out of the
   tile it belongs to, and the labels are read off the wall's data attributes,
   which the markup fills from content/impact.yml. */
(function () {
  var wall = document.querySelector('[data-sw]');
  if (!wall) return;
  var band = wall.closest('.band');
  var bar = band && band.querySelector('.sw-bar');
  var now = band && band.querySelector('.sw-now');
  var tiles = [].slice.call(wall.querySelectorAll('.sw-tile'));
  if (!bar || !now || !tiles.length) return;

  var MOVE = !REDUCED.matches && !!Element.prototype.animate;
  /* ONE CURVE, ONE CLOCK. The rows below, the reader unrolling and the page
     gliding all run on this curve for OPEN_MS, so they arrive together. It
     starts at about three times its average speed, not six: on a 700px drop
     that is the difference between a 60px first frame and a 120px one. */
  var CURVE = [0.25, 0.8, 0.25, 1];
  var MOVE_EASE = 'cubic-bezier(' + CURVE.join(', ') + ')';
  var EASE = 'cubic-bezier(0.16, 1, 0.3, 1)';
  var SHUT = 'cubic-bezier(0.4, 0, 0.2, 1)';
  var OPEN_MS = 600;
  var SHUT_MS = 300;
  /* The same curve in script, for the page glide. */
  var curve = (function (x1, y1, x2, y2) {
    var cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
    var cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
    return function (x) {
      if (x <= 0) return 0;
      if (x >= 1) return 1;
      var t = x;
      for (var i = 0; i < 8; i++) {
        var e = ((ax * t + bx) * t + cx) * t - x;
        var d = (3 * ax * t + 2 * bx) * t + cx;
        if (Math.abs(e) < 1e-5 || Math.abs(d) < 1e-6) break;
        t -= e / d;
      }
      return ((ay * t + by) * t + cy) * t;
    };
  }).apply(null, CURVE);

  var label = function (k) { return wall.getAttribute('data-' + k) || ''; };
  var esc = function (s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  };
  var fill = function (s, values) {
    return s.replace(/[{]([a-z]+)[}]/g, function (m, k) { return k in values ? values[k] : m; });
  };

  var reader = null; /* the open reader */
  var anchor = null; /* the tile whose row the reader opens beneath */
  var active = null; /* the tile whose story is in the reader */
  var busy = false;

  /* The no-script state is every story printed whole and no controls. Only
     now draw the controls, and make the tiles into what opens a story. */
  tiles.forEach(function (t) {
    var b = t.querySelector('.sw-open');
    b.setAttribute('aria-expanded', 'false');
    b.setAttribute('aria-controls', 'sw-reader');
  });
  bar.hidden = false;
  now.hidden = false;

  /* THE FEATURED STORIES FIRST (24 November 2026, at the content editor's
     word: twenty-two tiles was a long scroll). With script the wall opens on
     the stories marked featured, and "See all" shows the rest; choosing a way
     of working shows the whole wall filtered. Without script every story is
     printed, as before, and the button is never drawn. */
  var featured = tiles.filter(function (t) { return t.hasAttribute('data-featured'); });
  var allBar = band.querySelector('.sw-all-bar');
  var all = allBar && allBar.querySelector('.sw-all');
  var short = !!(all && featured.length && featured.length < tiles.length);
  if (short) {
    tiles.forEach(function (t) { t.hidden = featured.indexOf(t) < 0; });
    allBar.hidden = false;
  }
  function expand() {
    if (!short) return;
    short = false;
    allBar.hidden = true;
    all.setAttribute('aria-expanded', 'true');
  }

  function navH() { return parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--nav-h')) || 67; }
  function gap() { return parseFloat(getComputedStyle(wall).rowGap) || 16; }
  function shown() { return tiles.filter(function (t) { return !t.hidden; }); }
  /* offsetTop ignores transforms, so rows are read correctly even mid-animation. */
  function sameRow(a, b) { return a.offsetTop === b.offsetTop; }
  function rowEnd(t) {
    var list = shown(), end = t;
    for (var i = list.indexOf(t) + 1; i < list.length && sameRow(list[i], t); i++) end = list[i];
    return end;
  }
  function below(el) { return shown().filter(function (x) { return x.offsetTop > el.offsetTop; }); }
  function tops(list) {
    var m = new Map();
    list.forEach(function (x) { m.set(x, x.getBoundingClientRect().top); });
    return m;
  }
  /* Slides each element from where it was to where it is now. */
  function settle(before, ms) {
    if (!MOVE) return;
    before.forEach(function (top, x) {
      var dy = top - x.getBoundingClientRect().top;
      if (Math.abs(dy) > 0.5) {
        x.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: ms, easing: MOVE_EASE });
      }
    });
  }

  /* The page's own glide, on the reader's curve, so the two arrive together.
     A wheel or a touch hands the page straight back to the reader. */
  var glideId = 0;
  function glide(to, ms) {
    cancelAnimationFrame(glideId);
    to = Math.max(0, Math.round(to));
    var from = scrollY, d = to - from;
    if (Math.abs(d) < 2) return;
    if (!MOVE) { scrollTo({ top: to, behavior: 'instant' }); return; }
    var t0 = performance.now();
    (function step(t) {
      var k = Math.min(1, (t - t0) / ms);
      scrollTo({ top: from + d * curve(k), behavior: 'instant' });
      if (k < 1) glideId = requestAnimationFrame(step);
    })(t0);
  }
  ['wheel', 'touchstart'].forEach(function (ev) {
    addEventListener(ev, function () { cancelAnimationFrame(glideId); }, { passive: true });
  });

  /* ── the reader's content ─────────────────────────────────────────── */
  var ARROW_L = '<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><path d="M15 5l-7 7 7 7" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="square"/></svg>';
  var ARROW_R = '<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><path d="M9 5l7 7-7 7" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="square"/></svg>';
  var CROSS = '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" fill="none" stroke="currentColor" stroke-width="2.4"/></svg>';
  function content(t) {
    var list = shown(), i = list.indexOf(t);
    var el = document.createElement('div');
    el.className = 'sw-r-in';
    el.setAttribute('role', 'region');
    el.setAttribute('aria-labelledby', 'sw-r-title');

    var ph = document.createElement('figure');
    ph.className = 'sw-r-ph sw-ph';
    /* A plain card has no photograph to carry; its reader is the account alone. */
    var src = t.querySelector('.sw-media img');
    if (src) {
      var img = src.cloneNode(true);
      img.removeAttribute('loading');
      ph.appendChild(img);
    }
    var mark = t.querySelector('.sw-standin');
    if (mark) ph.appendChild(mark.cloneNode(true));

    var say = document.createElement('div');
    say.className = 'sw-r-say';
    say.appendChild(t.querySelector('.sw-fig').cloneNode(true));
    var h = document.createElement('h3');
    h.className = 'sw-r-t';
    h.id = 'sw-r-title';
    h.tabIndex = -1;
    h.textContent = t.querySelector('.sw-t').textContent;
    say.appendChild(h);
    [].forEach.call(t.querySelector('.sw-more').children, function (c) { say.appendChild(c.cloneNode(true)); });
    var nav = document.createElement('nav');
    nav.className = 'sw-r-nav';
    nav.setAttribute('aria-label', label('read-on'));
    nav.innerHTML =
      '<button class="sw-btn" type="button" data-step="-1"' + (i ? '' : ' disabled') + '>' + ARROW_L + esc(label('previous')) + '</button>' +
      '<button class="sw-btn" type="button" data-step="1"' + (i < list.length - 1 ? '' : ' disabled') + '>' + esc(label('next')) + ARROW_R + '</button>' +
      '<p class="sw-r-pos">' + fill(esc(label('position')), { n: '<b>' + (i + 1) + '</b>', total: String(list.length) }) + '</p>';
    say.appendChild(nav);
    var x = document.createElement('button');
    x.className = 'sw-x';
    x.type = 'button';
    x.setAttribute('aria-label', label('close'));
    x.innerHTML = CROSS;
    say.appendChild(x);

    el.appendChild(ph);
    el.appendChild(say);
    return el;
  }

  function mark(t) {
    if (active) {
      active.classList.remove('is-active');
      active.querySelector('.sw-open').setAttribute('aria-expanded', 'false');
    }
    active = t;
    if (t) {
      t.classList.add('is-active');
      t.querySelector('.sw-open').setAttribute('aria-expanded', 'true');
    }
  }
  /* The notch points at the story's tile while it is in the row above, and
     steps back when reading on has moved to a story elsewhere on the wall. */
  function aim() {
    var on = active && sameRow(active, anchor);
    reader.classList.toggle('is-detached', !on);
    if (on) reader.style.setProperty('--sw-nx', (active.offsetLeft + active.offsetWidth / 2 - reader.offsetLeft) + 'px');
  }
  /* A filtered wall's lead already shows its photograph at full width, so
     its reader carries the account alone. */
  function textOnly(t) {
    reader.classList.toggle(
      'is-text',
      t.classList.contains('sw-tile--plain') || (t.classList.contains('is-lead') && sameRow(t, anchor)),
    );
  }

  /* How far the page should travel: enough to show the whole reader, never so
     far that the tile it opened from leaves the screen. */
  function aimScroll() {
    var y = scrollY, top = navH(), r = reader.getBoundingClientRect(), t = anchor.getBoundingClientRect();
    /* Reveal the reader's foot, keeping at least the last 112px of its tile in view. */
    if (r.bottom > innerHeight - 24) return y + Math.min(r.bottom - innerHeight + 24, t.bottom - top - 112);
    /* Otherwise only a tile tucked under the header needs bringing down. */
    if (t.top < top + 8) return y + t.top - top - 16;
    return y;
  }

  /* ── open, read on, close ─────────────────────────────────────────── */
  function open(t) {
    mark(t);
    anchor = t;
    var before = tops(below(t));
    reader = document.createElement('li');
    reader.className = 'sw-reader';
    reader.id = 'sw-reader';
    reader.innerHTML = '<span class="sw-notch" aria-hidden="true"></span>';
    var inner = content(t);
    reader.appendChild(inner);
    rowEnd(t).after(reader);
    textOnly(t);
    aim();
    var g = gap();
    if (MOVE) {
      settle(before, OPEN_MS);
      /* The notch shows first, pointing, and the reader unrolls from it. */
      reader.animate(
        [{ clipPath: 'inset(-' + g + 'px 0 100% 0)' }, { clipPath: 'inset(-' + g + 'px 0 0 0)' }],
        { duration: OPEN_MS, easing: MOVE_EASE },
      );
      inner.animate(
        [{ opacity: 0, transform: 'translateY(14px)' }, { opacity: 1, transform: 'none' }],
        { duration: 460, delay: 150, easing: EASE, fill: 'backwards' },
      );
      if (!reader.classList.contains('is-text')) {
        inner.querySelector('img').animate([{ transform: 'scale(1.06)' }, { transform: 'none' }], { duration: 1000, easing: EASE });
      }
    } else if (Element.prototype.animate) {
      inner.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 220 });
    }
    glide(aimScroll(), OPEN_MS);
    reader.querySelector('h3').focus({ preventScroll: true });
  }

  function shut(instant) {
    if (!reader) return Promise.resolve();
    var r = reader, after = below(r);
    reader = null;
    anchor = null;
    mark(null);
    if (instant || !MOVE) {
      r.remove();
      return Promise.resolve();
    }
    var lift = r.offsetHeight + gap(), g = gap();
    var slides = after.map(function (x) {
      return x.animate([{ transform: 'none' }, { transform: 'translateY(-' + lift + 'px)' }], { duration: SHUT_MS, easing: SHUT, fill: 'forwards' });
    });
    r.querySelector('.sw-r-in').animate([{ opacity: 1 }, { opacity: 0 }], { duration: 140, fill: 'forwards' });
    var roll = r.animate(
      [{ clipPath: 'inset(-' + g + 'px 0 0 0)' }, { clipPath: 'inset(-' + g + 'px 0 100% 0)' }],
      { duration: SHUT_MS, easing: SHUT, fill: 'forwards' },
    );
    /* Removed and released in one frame, so the rows land exactly where they slid to. */
    return roll.finished.then(function () {
      r.remove();
      slides.forEach(function (a) { a.cancel(); });
    });
  }

  function close() {
    var t = active;
    busy = true;
    shut(false).then(function () {
      busy = false;
      if (!t) return;
      t.querySelector('.sw-open').focus({ preventScroll: true });
      var r = t.getBoundingClientRect();
      if (r.top < navH()) glide(scrollY + r.top - navH() - 16, 420);
    });
  }

  /* Another story into the open reader: the words cross over, the rows below
     follow any change in its height, and the reader itself does not move. */
  function swap(t) {
    var before = tops(below(reader));
    var old = reader.querySelector('.sw-r-in'), next = content(t);
    mark(t);
    var put = function () {
      old.replaceWith(next);
      textOnly(t);
      aim();
      settle(before, 420);
      if (MOVE) next.animate([{ opacity: 0, transform: 'translateY(10px)' }, { opacity: 1, transform: 'none' }], { duration: 380, easing: EASE });
      next.querySelector('h3').focus({ preventScroll: true });
      var r = reader.getBoundingClientRect();
      if (r.top < navH()) glide(scrollY + r.top - navH() - 16, 420);
    };
    if (!MOVE) return put();
    busy = true;
    old.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 130, easing: 'ease-in', fill: 'forwards' }).finished.then(function () {
      busy = false;
      put();
    });
  }

  function choose(t) {
    if (busy) return;
    if (!reader) return open(t);
    if (t === active) return close();
    if (sameRow(t, anchor)) return swap(t);
    busy = true;
    shut(false).then(function () {
      busy = false;
      open(t);
    });
  }

  function step(d) {
    if (busy || !reader) return;
    var list = shown(), i = list.indexOf(active) + d;
    if (i >= 0 && i < list.length) swap(list[i]);
  }

  /* ── filtering ────────────────────────────────────────────────────── */
  function flip(change) {
    if (!MOVE) return change();
    var before = new Map();
    tiles.forEach(function (t) { if (!t.hidden) before.set(t, t.getBoundingClientRect()); });
    change();
    tiles.forEach(function (t, i) {
      if (t.hidden) return;
      var b = t.getBoundingClientRect(), a = before.get(t);
      if (!a) {
        t.animate([{ opacity: 0, transform: 'translateY(18px)' }, { opacity: 1, transform: 'none' }], {
          duration: 460, delay: 60 + (i % 6) * 24, easing: EASE, fill: 'backwards',
        });
      } else if (Math.abs(a.left - b.left) + Math.abs(a.top - b.top) > 1) {
        t.animate([{ transform: 'translate(' + (a.left - b.left) + 'px,' + (a.top - b.top) + 'px)' }, { transform: 'none' }], {
          duration: 560, easing: EASE,
        });
      }
    });
  }

  function say(b) {
    var n = shown().length;
    if (!b.getAttribute('data-way')) {
      now.innerHTML = short
        ? '<b>' + fill(esc(label('featured-now')), { shown: String(n), total: String(tiles.length) }) + '</b> ' + esc(label('all-line'))
        : '<b>' + fill(esc(label('all-now')), { total: String(n) }) + '</b> ' + esc(label('all-line'));
      return;
    }
    now.innerHTML =
      '<b>' + fill(esc(label('way-now')), { shown: String(n), verb: esc(b.getAttribute('data-verb')) }) + '</b> ' +
      esc(b.getAttribute('data-line'));
  }

  function filter(b) {
    var id = b.getAttribute('data-way');
    shut(true);
    expand();
    flip(function () {
      tiles.forEach(function (t) {
        t.hidden = !!id && t.getAttribute('data-ways').split(' ').indexOf(id) < 0;
        t.classList.remove('is-lead');
      });
      wall.classList.toggle('is-filtered', !!id);
      /* The wall is ordered strongest first, so the first story left standing leads. */
      var lead = id && shown()[0];
      if (lead) lead.classList.add('is-lead');
    });
    [].forEach.call(bar.querySelectorAll('.sw-btn'), function (x) { x.setAttribute('aria-pressed', String(x === b)); });
    say(b);
  }

  /* ── wiring ───────────────────────────────────────────────────────── */
  bar.addEventListener('click', function (e) {
    var b = e.target.closest('.sw-btn');
    if (b) filter(b);
  });
  /* See all: the rest arrive below the featured row, and focus moves to the
     first of them, so a keyboard reader carries on where the new stories are. */
  if (short) {
    all.addEventListener('click', function () {
      var first = tiles.filter(function (t) { return t.hidden; })[0];
      shut(true);
      expand();
      flip(function () { tiles.forEach(function (t) { t.hidden = false; }); });
      say(bar.querySelector('.sw-btn[aria-pressed="true"]'));
      if (first) first.querySelector('.sw-open').focus({ preventScroll: true });
    });
  }
  wall.addEventListener('click', function (e) {
    if (e.target.closest('.sw-x')) return close();
    var s = e.target.closest('[data-step]');
    if (s) return step(Number(s.getAttribute('data-step')));
    var b = e.target.closest('.sw-open');
    if (b) choose(b.closest('.sw-tile'));
  });
  band.addEventListener('keydown', function (e) {
    if (!reader) return;
    if (e.key === 'Escape') {
      e.preventDefault();
      return close();
    }
    if (reader.contains(e.target)) {
      if (e.key === 'ArrowRight') { e.preventDefault(); step(1); }
      if (e.key === 'ArrowLeft') { e.preventDefault(); step(-1); }
    }
  });
  /* A change of width can move the anchor tile to another row; the reader follows. */
  var lastW = innerWidth, wait;
  addEventListener('resize', function () {
    if (innerWidth === lastW) return;
    lastW = innerWidth;
    clearTimeout(wait);
    wait = setTimeout(function () {
      if (!reader) return;
      rowEnd(anchor).after(reader);
      aim();
    }, 120);
  });
  say(bar.querySelector('.sw-btn'));
})();
