/**
 * The cue at the foot of the landing screen, and when it has done its job.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
/* ── THE SCROLL CUE ──────────────────────────────────────────────────────
   Decorative, so aria-hidden: it describes a gesture a screen reader does not
   make, and the page below is reachable without it. */
(function () {
  var host = document.querySelector('.hero--print');
  var lede = document.querySelector('.hero--print .hero-lede');
  if (!host || !lede) return;

  var el = document.createElement('div');
  el.className = 'cue';
  /* A stable hook for the gate that measures this thing at six viewport
     shapes. Costs a byte and means the check cannot drift away from what
     shipped by matching a class that was later renamed. */
  el.setAttribute('data-cue', '');
  el.setAttribute('aria-hidden', 'true');
  el.innerHTML = '<div class="cue-in">' +
    '<svg viewBox="0 0 21 33" fill="none" aria-hidden="true">' +
      '<rect x="0.75" y="0.75" width="19.5" height="31.5" rx="9.75"' +
        ' stroke="currentColor" stroke-width="1.5"/>' +
      '<circle cx="10.5" cy="8.5" r="1.9" fill="currentColor"/>' +
    '</svg><span>Scroll</span></div>';
  host.appendChild(el);

  /* How far an element is from where it is going. Both the cue and the
     standfirst are offset while their entrances run -- 14px and 26px -- and
     measuring either in flight answers a question nobody asked: the cue lands
     wrong and then jumps when anything re-measures.

     Parsed without a regular expression on purpose. This file is emitted from
     a template literal, which eats a backslash before the browser sees it,
     and a pattern that needs escaping is a pattern that can silently stop
     meaning what it says. */
  function dy(node) {
    var t = getComputedStyle(node).transform;
    if (!t || t.indexOf('matrix') !== 0) return 0;
    var i = t.indexOf('('), j = t.lastIndexOf(')');
    if (i < 0 || j < 0) return 0;
    var p = t.slice(i + 1, j).split(',');
    if (p.length === 16) return Number(p[13]) || 0;   /* matrix3d */
    return p.length >= 6 ? (Number(p[5]) || 0) : 0;
  }

  /* Glyph rectangles, not element boxes. A paragraph's box is the column's
     width whatever the last line does, so it reports collisions the type does
     not have and hides cues that were perfectly clear. */
  function lines() {
    var r = document.createRange();
    r.selectNodeContents(lede);
    var d = dy(lede);
    return [].slice.call(r.getClientRects())
      .filter(function (q) { return q.height > 1; })
      .map(function (q) { return { left: q.left, right: q.right, top: q.top - d, bottom: q.bottom - d }; });
  }

  var tail = null;
  function place() {
    el.style.visibility = '';
    el.style.bottom = '';
    var rows = lines();
    if (!rows.length) return;
    var last = rows[rows.length - 1];

    /* The cue's own last line on the standfirst's last line. Baselines, not
       boxes: two sizes of type have different half-leading, so matching boxes
       leaves the words a few pixels out, and the words are what is read. */
    var word = el.querySelector('span');
    var wr = document.createRange();
    wr.selectNodeContents(word);
    var wq = [].slice.call(wr.getClientRects()).filter(function (q) { return q.height > 1; });
    if (!wq.length) return;
    var cd = dy(el);
    var box = el.getBoundingClientRect();
    if (tail === null) tail = (box.bottom - cd) - (wq[wq.length - 1].bottom - cd);

    /* Only where there is a corner to stand in. Below that it stays low. */
    if (box.left >= Math.max.apply(null, rows.map(function (q) { return q.right; })) + 20) {
      el.style.bottom = Math.round(host.getBoundingClientRect().bottom - last.bottom - tail) + 'px';
    }

    /* And if even that sits on the words, it goes. A cue overlapping the
       sentence it points past is worse than no cue. */
    var b = el.getBoundingClientRect();
    var c = { left: b.left, right: b.right, top: b.top - cd, bottom: b.bottom - cd };
    var hits = rows.some(function (q) {
      return !(c.right <= q.left || c.left >= q.right || c.bottom <= q.top || c.top >= q.bottom);
    });
    el.style.visibility = hits ? 'hidden' : '';
  }

  var queued = false;
  addEventListener('resize', function () {
    if (queued) return;
    queued = true;
    requestAnimationFrame(function () { queued = false; tail = null; place(); });
  }, { passive: true });

  place();
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(place);

  /* Leaves as the reader leaves the first screen, and comes back if they
     return. Position, not event, so it can never get stuck gone. */
  var ticking = false;
  function fade() {
    ticking = false;
    if (scrollY > innerHeight * 0.14) el.setAttribute('data-gone', '');
    else el.removeAttribute('data-gone');
  }
  addEventListener('scroll', function () {
    if (!ticking) { ticking = true; requestAnimationFrame(fade); }
  }, { passive: true });
  fade();
})();

