/**
 * Our areas of work: the portfolio overview opens below its row.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 *
 * The spotlight (19 November 2026) is added at the end, after the lifted code,
 * which is left exactly as it was. It closes over REDUCED, as history.js does,
 * so the frozen reference can carry the same body.
 */
import { REDUCED } from './motion-base.js';
/* ---------------------------------------------------------------------
   Our areas of work: the portfolio overview opens below its row.
   Chosen from six placements built and compared side by side; this is the
   one that keeps the grid of prints intact. */
(function () {
  var grid = document.querySelector('.acards');
  if (!grid) return;
  var cards = [].slice.call(grid.querySelectorAll('.acard'));
  var panels = [].slice.call(grid.querySelectorAll('.acard-panel'));
  if (!cards.length || cards.length !== panels.length) return;

  /* The no-script state is every overview open. Close them, and only now
     reveal the controls that close and open them. */
  panels.forEach(function (p) { p.hidden = true; });
  var open = -1;

  /* Where the gold tab goes. Measured against the laid-out boxes rather than
     computed from an index, for the same reason the row is: these cards are
     not all the same width. Both rectangles are border boxes and the tab is
     positioned against the panel's padding box, which with no border on the
     panel is the same edge. */
  function mark() {
    if (open < 0) return;
    var c = cards[open].getBoundingClientRect();
    var p = panels[open].getBoundingClientRect();
    panels[open].style.setProperty('--mark-x', (c.left - p.left) + 'px');
    panels[open].style.setProperty('--mark-w', c.width + 'px');
  }

  function shut() {
    if (open < 0) return;
    cards[open].removeAttribute('data-open');
    cards[open].querySelector('.acard-go').setAttribute('aria-expanded', 'false');
    panels[open].hidden = true;
    open = -1;
  }

  cards.forEach(function (card, i) {
    var go = card.querySelector('.acard-go');
    if (!go) return;
    go.hidden = false;
    go.addEventListener('click', function () {
      var was = open;
      shut();
      if (was === i) return;

      /* Which cards share a row with this one. Measured, because the cards
         are not all the same width and an index cannot tell you. */
      var top = card.offsetTop;
      var last = i;
      for (var k = 0; k < cards.length; k++) {
        if (Math.abs(cards[k].offsetTop - top) <= 2) last = k;
      }
      cards.forEach(function (c, k) { c.style.order = (k + 1) * 10; });
      panels[i].style.order = (last + 1) * 10 + 5;

      open = i;
      card.setAttribute('data-open', '');
      go.setAttribute('aria-expanded', 'true');
      panels[i].hidden = false;
      mark();
      /* The panel takes focus so a keyboard reader lands in what just opened
         rather than back at the top of the grid. */
      panels[i].focus({ preventScroll: true });
    });
  });

  /* A row can change which cards it holds when the grid reflows, so an open
     drawer has to be re-placed rather than left where it was. */
  var queued = false;
  addEventListener('resize', function () {
    if (open < 0 || queued) return;
    queued = true;
    requestAnimationFrame(function () {
      queued = false;
      if (open < 0) return;
      var top = cards[open].offsetTop, last = open;
      for (var k = 0; k < cards.length; k++) {
        if (Math.abs(cards[k].offsetTop - top) <= 2) last = k;
      }
      panels[open].style.order = (last + 1) * 10 + 5;
      /* After the re-place, not before: the card may have moved to a different
         row and the tab has to follow it there. */
      mark();
    });
  }, { passive: true });

  /* ---------------------------------------------------------------------
     THE SPOTLIGHT (19 November 2026). The look is all in work.css; what is
     here makes an opened overview something a reader actually arrives in.

     1. IT IS BROUGHT INTO VIEW. A card low on the screen used to open its
        overview below the fold: measured at 1440 x 900, Health Systems
        Strengthening's opened at y = 840, and the only visible change was
        the button turning gold. If an overview's top lands in the lower part
        of the screen, the page now travels until the card's name sits under
        the header, at the anchor offset every [id] carries (read from the
        card's own button, as history.js does). It travels on the curve and
        timing of the page's own in-page travel (anchors.js): sine in and
        out, longer for longer journeys, and it gives way the moment the
        reader scrolls.
     2. ITS CONTROLS WORK. Close at its head and foot shuts it and hands focus
        back to the card's button; Escape does the same from inside it; Next
        opens the next portfolio and travels to it. */
  var n = cards.length;
  var gos = cards.map(function (c) { return c.querySelector('.acard-go'); });
  var run = 0;
  function glide(to) {
    to = Math.max(0, Math.min(to, document.documentElement.scrollHeight - innerHeight));
    var from = scrollY, d = to - from;
    if (Math.abs(d) < 4) return;
    if (REDUCED.matches) { scrollTo(0, to); return; }
    var ms = Math.min(1900, Math.max(560, 420 + Math.abs(d) / 16));
    var me = ++run, t0 = null;
    requestAnimationFrame(function frame(now) {
      if (me !== run) return;
      if (t0 === null) t0 = now;
      var t = Math.min(1, (now - t0) / ms);
      scrollTo(0, Math.round(from + d * (0.5 - Math.cos(Math.PI * t) / 2)));
      if (t < 1) requestAnimationFrame(frame);
    });
  }
  ['wheel', 'touchstart', 'keydown'].forEach(function (ev) {
    addEventListener(ev, function () { run++; }, { passive: true });
  });
  function bring(i, always) {
    var head = cards[i].querySelector('.acard-head').getBoundingClientRect();
    var margin = parseFloat(getComputedStyle(gos[i]).scrollMarginTop) || 0;
    if (!always && head.top >= margin && panels[i].getBoundingClientRect().top < innerHeight * 0.62) return;
    glide(scrollY + head.top - margin);
  }

  /* Registered after the lifted handler, so it runs once the drawer is open.
     Only for a reader's own click, or this block's own Next: Past work and
     the header's menus open overviews from script and travel there
     themselves, and two journeys at once fight frame by frame. */
  var stepping = false;
  gos.forEach(function (go, i) {
    go.addEventListener('click', function (e) {
      if (open === i && (e.isTrusted || stepping)) bring(i, stepping);
      stepping = false;
    });
  });
  function close(i) {
    gos[i].click();
    gos[i].focus({ preventScroll: true });
    bring(i, false);
  }
  panels.forEach(function (p, i) {
    [].forEach.call(p.querySelectorAll('[data-ov-close]'), function (b) { b.hidden = false; });
    p.querySelector('.ov-foot').hidden = false;
    p.addEventListener('click', function (e) {
      if (e.target.closest('[data-ov-close]')) { close(i); return; }
      if (e.target.closest('[data-ov-next]')) {
        stepping = true;
        gos[(i + 1) % n].click();
      }
    });
    p.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && open === i) close(i);
    });
  });
})();

