/**
 * Every marquee band, each scrolling only if its content overflows and
 * stopping when a reader wants to read it.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
import { REDUCED } from './motion-base.js';

/* Every marquee band on the page -- the states band across the top is the only
   one since the voices strip was removed, and the engine is written for a set
   rather than for that one because it took the first .names it found once and
   drove nothing else. Each scrolls only if its content overflows, and stops
   when a reader wants to read it. */
[].slice.call(document.querySelectorAll('.names')).forEach(function (band) {
  const track = band.querySelector('.names-track');
  if (!track || REDUCED.matches) return;
  /* Measure in the single-line state, then keep it only if it overflows: the
     wrapped state is the default so a reader who never sees the marquee still
     gets every item. */
  band.classList.add('is-marquee');
  if (track.scrollWidth <= band.clientWidth) {
    band.classList.remove('is-marquee');
    return;
  }
  const clone = track.cloneNode(true);
  clone.setAttribute('aria-hidden', 'true');
  clone.removeAttribute('tabindex');
  /* Wrap in place. Assuming the track was a direct child of the band broke the
     moment one of them was nested in a grid to align it with the page. */
  const parent = track.parentNode;
  parent.insertBefore(clone, track.nextSibling);
  const holder = document.createElement('div');
  holder.style.display = 'flex';
  /* max-content, and the whole loop depends on it. The animation moves the
     holder by translateX(-50%), which is one track only when the holder is as
     wide as its two children. A flex container in a block context takes its
     containing block's width instead and lets the children overflow, so the
     travel was half a BAND rather than one track -- measured, the states
     marquee was crossing 720px of a 1950px track and snapping back mid-loop,
     and running at 21px/s against the 58 it asks for. Both faults are the same
     missing declaration. */
  holder.style.width = 'max-content';
  holder.style.flex = '0 0 auto';
  parent.insertBefore(holder, track);
  holder.appendChild(track);
  holder.appendChild(clone);
  /* Speed comes from the band, in pixels per second. A fixed DURATION was the
     original fault — a longer track simply moved faster — and a single fixed
     SPEED is the next one down: a state name going past and a paragraph of
     someone's words are different reading tasks. */
  const SPEED = parseFloat(getComputedStyle(band).getPropertyValue('--marquee-speed')) || 58;
  holder.animate(
    [{ transform: 'translateX(0)' }, { transform: 'translateX(-50%)' }],
    { duration: Math.max(8000, (track.scrollWidth / SPEED) * 1000), iterations: Infinity, easing: 'linear' }
  );
  const anims = holder.getAnimations();
  const stop = function () { anims.forEach(function (a) { a.pause(); }); };
  const go = function () { anims.forEach(function (a) { a.play(); }); };
  band.addEventListener('mouseenter', stop);
  band.addEventListener('mouseleave', go);
  /* Focus, not just hover. The track carries tabindex so this can actually
     fire — the previous version listened for focusin on a band containing
     nothing focusable, which meant moving content with no keyboard way to
     stop it. */
  band.addEventListener('focusin', stop);
  band.addEventListener('focusout', go);
});

