/**
 * A tap opens a portrait.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
/* A tap opens a portrait.

   Hover and keyboard focus are handled by the stylesheet alone; this exists
   for the device that has neither. aria-expanded carries the state, so one
   attribute drives the rule and tells a screen reader what happened, and
   only one card is open at a time because nine open cards is a wall with no
   faces on it.

   Pointer type rather than a media query: a laptop with a touchscreen has
   both, and on that machine a tap should still open the card. */
(function () {
  var btns = [].slice.call(document.querySelectorAll('.tm-b'));
  if (!btns.length) return;
  btns.forEach(function (b) {
    b.addEventListener('click', function () {
      var open = b.getAttribute('aria-expanded') === 'true';
      btns.forEach(function (o) { o.setAttribute('aria-expanded', 'false'); });
      b.setAttribute('aria-expanded', open ? 'false' : 'true');
    });
  });
  /* Escape closes, for a keyboard that opened one with Enter. */
  addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    btns.forEach(function (o) { o.setAttribute('aria-expanded', 'false'); });
  });
})();

