/**
 * The laydown. A band is marked in when it arrives, and the stylesheet does
 * the rest.
 *
 * Lifted verbatim from the approved page's one script, comments and all. Read
 * them before changing a rule: they record what was measured and what was
 * tried the other way. The IIFE wrapper is kept although a module already
 * gives it: removing it would re-indent the whole file and bury the real
 * history in a diff nobody can read.
 */
import { onReveal } from './motion-base.js';
/* The scroll motion. The band is marked "in" when it arrives and the
   stylesheet lays its contents down in reading order.

   Reduced motion never fires this, which is why the start state is inside a
   no-preference query — otherwise this is the line that would hide the page
   from the people who asked for less movement. */
(function () {
  /* Reading order is the stagger, so each element that moves carries its own
     delay. The set is the rail followed by the chapter's own children — NOT
     the children of .inner, which on a rail band is two grid columns and would
     quietly reduce every chapter to a two-step fade. Capped: a band with
     twenty rows should not take two seconds to finish. */
  [].slice.call(document.querySelectorAll('.band[data-lay]')).forEach(function (band) {
    var rail = band.querySelector('.rail');
    var lay = band.querySelector('.lay');
    var order = (rail ? [rail] : []).concat(lay ? [].slice.call(lay.children) : []);
    order.forEach(function (el, i) {
      el.style.setProperty('--d', Math.min(i * 70, 350) + 'ms');
    });
  });

  onReveal('.band[data-lay]', function (el) { el.classList.add('in'); });
})();

