/**
 * Past work: the cascade.
 *
 * Chosen by the user on 25 November 2026 from six variations built into
 * copies of this page in the design archive (pastwork-lab, variation 5); it
 * replaces the register chosen on 16 November. Written the way the lifted
 * modules are, a body that closes over REDUCED, so that the frozen reference
 * can carry the same body in its one inline script and
 * tests/parity/assembly.mjs can hold the two to the same hash.
 *
 * It runs after overview.js because it opens the portfolio overviews that
 * module wires up.
 */
import { REDUCED } from './motion-base.js';
/* ---------------------------------------------------------------------
   Past work: the cascade. Open a step for its account, and go up to the
   portfolio that carries that work today. */
(function () {
  var root = document.querySelector('.pw5');
  if (!root) return;

  /* The no-script state is every account printed open. Only now close them,
     and make the steps into what opens one. */
  [].slice.call(root.querySelectorAll('.pw5-row')).forEach(function (b) {
    b.setAttribute('aria-expanded', 'false');
  });
  root.classList.add('pw5--on');

  root.addEventListener('click', function (e) {
    var b = e.target.closest('.pw5-row');
    if (!b) return;
    var li = b.closest('.pw5-r');
    var open = !li.classList.contains('is-open');
    li.classList.toggle('is-open', open);
    b.setAttribute('aria-expanded', String(open));
  });

  /* Up to the portfolio that carries the work now, with its overview open.
     The link's own address is that overview, which is where a reader without
     script lands: for them every overview is already open. */
  [].slice.call(root.querySelectorAll('.pw-today')).forEach(function (a) {
    a.addEventListener('click', function (e) {
      var code = a.getAttribute('data-code');
      var btn = document.getElementById('ovb-' + code);
      var card = btn && btn.closest('.acard');
      if (!card || btn.hidden) return;
      e.preventDefault();

      /* Open first, measure after. Opening this overview shuts any other, and
         one open above this card would move it after it had been measured.
         overview.js gives the opened panel focus; an overview that was open
         already is given it here, so a keyboard reader lands in it either way. */
      if (btn.getAttribute('aria-expanded') !== 'true') {
        btn.click();
      } else {
        var panel = document.getElementById('ov-' + code);
        if (panel) panel.focus({ preventScroll: true });
      }

      /* Where it stops is the page's anchor offset, read back from the card's
         own button, which carries an id and so the [id] scroll margin. */
      var margin = parseFloat(getComputedStyle(btn).scrollMarginTop) || 0;
      var top = card.getBoundingClientRect().top + scrollY - margin;
      scrollTo({ top: Math.max(0, top), behavior: REDUCED.matches ? 'auto' : 'smooth' });

      card.classList.remove('pw-here');
      void card.offsetWidth;
      card.classList.add('pw-here');
    });
  });
})();
